CREATE OR REPLACE FUNCTION public.trg_movcc_append_only_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('app.allow_ledger_repair', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
